const DEFAULT_SETTINGS = {
  publicBaseUrl: "",
  inworldApiKey: "",
  inworldLlmModel: "",
  inworldSttModel: "",
  inworldSttLanguage: "",
  qwenApiKey: "",
  qwenModel: "",
  openrouterApiKey: "",
  openrouterBuzzinModel: "",
};

const SETTINGS_KEY = "app-settings";

export function maskApiKey(key) {
  const trimmed = String(key || "").trim();
  if (!trimmed) return "";
  if (trimmed.length <= 8) return "••••••••";
  return `••••${trimmed.slice(-4)}`;
}

export function normalizePublicBaseUrl(url) {
  const trimmed = String(url || "").trim().replace(/\/$/, "");
  if (!trimmed) return "";
  if (!/^https?:\/\/.+/i.test(trimmed)) {
    throw new Error("URL must start with http:// or https://");
  }
  return trimmed;
}

export async function readSettings(env) {
  const raw = await env.SETTINGS.get(SETTINGS_KEY, "json");
  if (!raw || typeof raw !== "object") return { ...DEFAULT_SETTINGS };
  return {
    publicBaseUrl:
      typeof raw.publicBaseUrl === "string" ? raw.publicBaseUrl.trim().replace(/\/$/, "") : "",
    inworldApiKey: typeof raw.inworldApiKey === "string" ? raw.inworldApiKey.trim() : "",
    inworldLlmModel: typeof raw.inworldLlmModel === "string" ? raw.inworldLlmModel.trim() : "",
    inworldSttModel: typeof raw.inworldSttModel === "string" ? raw.inworldSttModel.trim() : "",
    inworldSttLanguage:
      typeof raw.inworldSttLanguage === "string" ? raw.inworldSttLanguage.trim() : "",
    qwenApiKey: typeof raw.qwenApiKey === "string" ? raw.qwenApiKey.trim() : "",
    qwenModel: typeof raw.qwenModel === "string" ? raw.qwenModel.trim() : "",
    openrouterApiKey:
      typeof raw.openrouterApiKey === "string" ? raw.openrouterApiKey.trim() : "",
    openrouterBuzzinModel:
      typeof raw.openrouterBuzzinModel === "string" ? raw.openrouterBuzzinModel.trim() : "",
  };
}

export async function writeSettings(env, partial) {
  const current = await readSettings(env);
  const next = { ...current, ...partial };

  if (typeof next.publicBaseUrl === "string") {
    next.publicBaseUrl = next.publicBaseUrl.trim().replace(/\/$/, "");
  }
  for (const key of [
    "inworldApiKey",
    "inworldLlmModel",
    "inworldSttModel",
    "inworldSttLanguage",
    "qwenApiKey",
    "qwenModel",
    "openrouterApiKey",
    "openrouterBuzzinModel",
  ]) {
    if (typeof next[key] === "string") next[key] = next[key].trim();
  }

  await env.SETTINGS.put(SETTINGS_KEY, JSON.stringify(next));
  return next;
}

export async function getPublicBaseUrl(env) {
  const saved = (await readSettings(env)).publicBaseUrl;
  return saved || String(env.PUBLIC_BASE_URL || "").replace(/\/$/, "");
}

export async function getInworldApiKey(env) {
  const saved = (await readSettings(env)).inworldApiKey;
  return saved || String(env.INWORLD_API_KEY || "").trim();
}

export async function getInworldLlmModel(env) {
  const saved = (await readSettings(env)).inworldLlmModel;
  return saved || String(env.INWORLD_LLM_MODEL || "auto").trim() || "auto";
}

export async function getInworldSttModel(env) {
  const saved = (await readSettings(env)).inworldSttModel;
  return saved || String(env.INWORLD_STT_MODEL || "inworld/inworld-stt-1").trim();
}

export async function getInworldSttLanguage(env) {
  const saved = (await readSettings(env)).inworldSttLanguage;
  return saved || String(env.INWORLD_STT_LANGUAGE || "en").trim() || "en";
}

export async function getQwenApiKey(env) {
  const saved = (await readSettings(env)).qwenApiKey;
  return saved || String(env.QWEN_API_KEY || "").trim();
}

export async function getQwenModel(env) {
  const saved = (await readSettings(env)).qwenModel;
  return saved || String(env.QWEN_MODEL || "qwen-plus").trim() || "qwen-plus";
}

export async function getOpenRouterApiKey(env) {
  const saved = (await readSettings(env)).openrouterApiKey;
  return saved || String(env.OPENROUTER_API_KEY || "").trim();
}

export async function getOpenRouterBuzzinModel(env) {
  const saved = (await readSettings(env)).openrouterBuzzinModel;
  return (
    saved ||
    String(env.OPENROUTER_BUZZIN_MODEL || "mistralai/voxtral-small-24b-2507").trim()
  );
}

export async function buildConfigResponse(env, scoreStats) {
  const settings = await readSettings(env);
  const effectiveInworldKey = await getInworldApiKey(env);
  const effectiveInworldLlmModel = await getInworldLlmModel(env);
  const publicBaseUrl = await getPublicBaseUrl(env);

  return {
    publicBaseUrl: settings.publicBaseUrl || "",
    envDefault: String(env.PUBLIC_BASE_URL || "").replace(/\/$/, ""),
    effectivePublicBaseUrl: publicBaseUrl,
    inworldApiKeySaved: !!settings.inworldApiKey,
    inworldEnvDefaultConfigured: !!env.INWORLD_API_KEY,
    inworldApiKeyConfigured: !!effectiveInworldKey,
    inworldApiKeyMasked: maskApiKey(effectiveInworldKey),
    inworldLlmModelSaved: settings.inworldLlmModel || "",
    inworldLlmModelEnvDefault: String(env.INWORLD_LLM_MODEL || "auto"),
    effectiveInworldLlmModel,
    inworldSttModelSaved: settings.inworldSttModel || "",
    inworldSttModelEnvDefault: String(env.INWORLD_STT_MODEL || "inworld/inworld-stt-1"),
    effectiveInworldSttModel: await getInworldSttModel(env),
    inworldSttLanguageSaved: settings.inworldSttLanguage || "",
    inworldSttLanguageEnvDefault: String(env.INWORLD_STT_LANGUAGE || "en"),
    effectiveInworldSttLanguage: await getInworldSttLanguage(env),
    qwenApiKeySaved: !!settings.qwenApiKey,
    qwenEnvDefaultConfigured: !!env.QWEN_API_KEY,
    qwenApiKeyConfigured: !!(await getQwenApiKey(env)),
    qwenApiKeyMasked: maskApiKey(await getQwenApiKey(env)),
    qwenModelSaved: settings.qwenModel || "",
    qwenModelEnvDefault: String(env.QWEN_MODEL || "qwen-plus"),
    effectiveQwenModel: await getQwenModel(env),
    openrouterApiKeySaved: !!settings.openrouterApiKey,
    openrouterEnvDefaultConfigured: !!env.OPENROUTER_API_KEY,
    openrouterApiKeyConfigured: !!(await getOpenRouterApiKey(env)),
    openrouterApiKeyMasked: maskApiKey(await getOpenRouterApiKey(env)),
    openrouterBuzzinModelSaved: settings.openrouterBuzzinModel || "",
    openrouterBuzzinModelEnvDefault: String(
      env.OPENROUTER_BUZZIN_MODEL || "mistralai/voxtral-small-24b-2507"
    ),
    effectiveOpenRouterBuzzinModel: await getOpenRouterBuzzinModel(env),
    notificationPreview: {
      session_id: "123456",
      class_name: "Example class",
      teacher_name: "Example teacher",
      base_endpoint: publicBaseUrl,
    },
    studentDatabase: scoreStats,
  };
}

export async function buildNotificationData(env, extra = {}) {
  return {
    ...extra,
    base_endpoint: await getPublicBaseUrl(env),
  };
}
