import {
  getInworldApiKey,
  getInworldLlmModel,
  getInworldSttModel,
  getInworldSttLanguage,
  getOpenRouterApiKey,
  getOpenRouterBuzzinModel,
  getPublicBaseUrl,
} from "../env.js";

const INWORLD_API_BASE = "https://api.inworld.ai";
const INWORLD_BUZZIN_TTS_VOICE_ID = "default-zylgts2tamenvybeti3z0w__uncle_tommy";
const INWORLD_TTS_MODEL_ID = "inworld-tts-1.5-max";
const OPENROUTER_API_BASE = "https://openrouter.ai/api/v1";
const TRANSCRIBE_DEFAULT_MODEL = "mistralai/voxtral-small-24b-2507";
const TRANSCRIBE_MAX_AUDIO_BYTES = 25 * 1024 * 1024;
export const TRANSCRIBE_PROMPT =
  "Listen to this audio and respond with exactly two sections:\n\n" +
  "Transcript:\n" +
  "Write exactly what was spoken, verbatim. No extra commentary in this section.\n\n" +
  "Pronunciation feedback:\n" +
  "Comment on pronunciation quality. Note any mispronounced or unclear words, " +
  "stress, rhythm, or intonation issues, and give brief constructive tips. " +
  "If pronunciation is generally good, say so and mention any small improvements.";

async function parseInworldResponse(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { message: text || res.statusText };
  }
}

function inworldErrorMessage(data, status) {
  return data?.message || data?.error?.message || `Inworld API returned ${status}.`;
}

export async function inworldTtsSynthesize(env, text, voiceId = INWORLD_BUZZIN_TTS_VOICE_ID) {
  const key = await getInworldApiKey(env);
  const trimmed = String(text || "").trim();
  if (!key) throw new Error("Inworld API key not configured.");
  if (!trimmed) throw new Error("No text to synthesize.");

  const res = await fetch(`${INWORLD_API_BASE}/tts/v1/voice`, {
    method: "POST",
    headers: {
      Authorization: `Basic ${key}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      text: trimmed,
      voiceId: String(voiceId || INWORLD_BUZZIN_TTS_VOICE_ID).trim() || INWORLD_BUZZIN_TTS_VOICE_ID,
      modelId: INWORLD_TTS_MODEL_ID,
      audioConfig: { audioEncoding: "MP3", sampleRateHertz: 24000 },
    }),
  });
  const data = await parseInworldResponse(res);
  if (!res.ok) throw new Error(`TTS: ${inworldErrorMessage(data, res.status)}`);
  const audioContent = String(data?.audioContent || "").trim();
  if (!audioContent) throw new Error("TTS: No audio returned.");
  return { audioContent, format: "mp3" };
}

async function parseOpenRouterResponse(res) {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return { message: text || res.statusText };
  }
}

function openRouterErrorMessage(data, status) {
  const parts = [];
  const primary = data?.error?.message || data?.message;
  if (primary) parts.push(primary);
  if (data?.error?.metadata) parts.push(JSON.stringify(data.error.metadata));
  if (data?.error?.code) parts.push(`code: ${data.error.code}`);
  return parts.join(" — ") || `OpenRouter API returned ${status}.`;
}

export function extractOpenRouterMessageText(data) {
  const choices = data?.choices || [];
  if (!choices.length) return "";
  const content = choices[0]?.message?.content;
  if (typeof content === "string") return content.trim();
  if (Array.isArray(content)) {
    return content
      .filter((part) => part?.type === "text")
      .map((part) => String(part.text || "").trim())
      .filter(Boolean)
      .join(" ")
      .trim();
  }
  return "";
}

export async function openRouterLlmComplete(env, apiKey, model, messages, maxTokens = 256) {
  const key = String(apiKey || (await getOpenRouterApiKey(env)) || "").trim();
  if (!key) throw new Error("OpenRouter is not configured. Add an API key in Config.");

  const llmModel =
    String(model || (await getOpenRouterBuzzinModel(env)) || TRANSCRIBE_DEFAULT_MODEL).trim() ||
    TRANSCRIBE_DEFAULT_MODEL;

  const res = await fetch(`${OPENROUTER_API_BASE}/chat/completions`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${key}`,
      "Content-Type": "application/json",
      "HTTP-Referer": await getPublicBaseUrl(env),
      "X-Title": "Lango Buzz In",
    },
    body: JSON.stringify({ model: llmModel, messages, max_tokens: maxTokens }),
  });
  const data = await parseOpenRouterResponse(res);
  if (!res.ok) throw new Error(`LLM (${llmModel}): ${openRouterErrorMessage(data, res.status)}`);
  return extractOpenRouterMessageText(data);
}

export async function transcribeOpenRouterAudio(env, { apiKey, model, audioBuffer, format, prompt, maxTokens = 1024 }) {
  const key = String(apiKey || (await getOpenRouterApiKey(env)) || "").trim();
  if (!key) throw new Error("OpenRouter is not configured. Add an API key in Config.");

  const buzzinModel =
    String(model || (await getOpenRouterBuzzinModel(env)) || TRANSCRIBE_DEFAULT_MODEL).trim() ||
    TRANSCRIBE_DEFAULT_MODEL;

  const bytes = audioBuffer instanceof Uint8Array ? audioBuffer : new Uint8Array(audioBuffer);
  if (!bytes.length) throw new Error("The selected audio file is empty.");
  if (bytes.length > TRANSCRIBE_MAX_AUDIO_BYTES) throw new Error("Audio file is too large (max 25 MB).");

  const audioFormat = String(format || "webm").trim().toLowerCase().replace(/^\./, "") || "webm";
  let binary = "";
  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
  const base64Data = btoa(binary);

  const res = await fetch(`${OPENROUTER_API_BASE}/chat/completions`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${key}`,
      "Content-Type": "application/json",
      "HTTP-Referer": await getPublicBaseUrl(env),
      "X-Title": "OpenRouter Audio Transcribe",
    },
    body: JSON.stringify({
      model: buzzinModel,
      messages: [
        {
          role: "user",
          content: [
            { type: "input_audio", input_audio: { data: base64Data, format: audioFormat } },
            { type: "text", text: prompt },
          ],
        },
      ],
      max_tokens: maxTokens,
    }),
  });

  const data = await parseOpenRouterResponse(res);
  if (!res.ok) {
    const err = new Error(`Transcription (${buzzinModel}): ${openRouterErrorMessage(data, res.status)}`);
    err.openRouterDetails = data;
    throw err;
  }

  const text = extractOpenRouterMessageText(data);
  if (!text) throw new Error("Could not transcribe the audio. Try another file or model.");
  return text;
}

export async function inworldLlmComplete(env, apiKey, model, messages, maxTokens = 256) {
  const llmModel = String(model || "auto").trim() || "auto";
  const res = await fetch(`${INWORLD_API_BASE}/v1/chat/completions`, {
    method: "POST",
    headers: {
      Authorization: `Basic ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ model: llmModel, messages, max_tokens: maxTokens }),
  });
  const data = await parseInworldResponse(res);
  if (!res.ok) throw new Error(`LLM (${llmModel}): ${inworldErrorMessage(data, res.status)}`);
  return data?.choices?.[0]?.message?.content?.trim?.() || "";
}

export async function testInworldApiKey(env, apiKey, llmModel) {
  const key = String(apiKey || "").trim();
  if (!key) throw new Error("No Inworld API key to test.");

  const started = Date.now();
  const tts = await inworldTtsSynthesize(env, "Inworld TTS is working.", INWORLD_BUZZIN_TTS_VOICE_ID);
  const llm = await inworldLlmComplete(env, key, llmModel, [{ role: "user", content: "Reply with exactly: OK" }], 16);

  return {
    ok: true,
    latencyMs: Date.now() - started,
    tts: { ok: true, voiceId: INWORLD_BUZZIN_TTS_VOICE_ID, modelId: INWORLD_TTS_MODEL_ID },
    llm: { ok: true, model: llmModel || "auto", reply: llm.slice(0, 200) },
    stt: { ok: true, modelId: await getInworldSttModel(env) },
  };
}

export async function testOpenRouterBuzzinModel(env, apiKey, model) {
  const key = String(apiKey || (await getOpenRouterApiKey(env)) || "").trim();
  if (!key) throw new Error("OpenRouter is not configured.");

  const buzzinModel =
    String(model || (await getOpenRouterBuzzinModel(env)) || TRANSCRIBE_DEFAULT_MODEL).trim();
  const started = Date.now();
  const reply = await openRouterLlmComplete(env, key, buzzinModel, [{ role: "user", content: "Reply with exactly: OK" }], 16);
  return { ok: true, model: buzzinModel, latencyMs: Date.now() - started, reply: reply.slice(0, 200) };
}

export async function testQwenApiKey(env, apiKey, model) {
  const key = String(apiKey || "").trim();
  if (!key) throw new Error("No Qwen API key to test.");

  const qwenModel = String(model || "qwen-plus").trim() || "qwen-plus";
  const base = String(env.QWEN_API_BASE || "https://dashscope.aliyuncs.com/compatible-mode/v1").replace(/\/$/, "");
  const started = Date.now();

  const res = await fetch(`${base}/chat/completions`, {
    method: "POST",
    headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      model: qwenModel,
      messages: [{ role: "user", content: "Reply with exactly: OK" }],
      max_tokens: 16,
    }),
  });
  const text = await res.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch {
    data = { message: text };
  }
  if (!res.ok) throw new Error(data?.error?.message || data?.message || "Qwen API test failed.");

  return {
    ok: true,
    latencyMs: Date.now() - started,
    llm: { ok: true, model: qwenModel, reply: (data?.choices?.[0]?.message?.content || "").slice(0, 200) },
  };
}

export function audioFormatFromFilename(filename) {
  const match = String(filename || "").match(/\.([a-z0-9]+)$/i);
  return match ? match[1].toLowerCase() : "webm";
}

// Re-export for room engine
export { getInworldApiKey, getInworldSttModel, getInworldSttLanguage, getOpenRouterApiKey, getOpenRouterBuzzinModel };
