export function pickToken(req) {
  const auth = req.headers.get("authorization") || "";
  if (auth.startsWith("Bearer ")) return auth.slice(7);
  return auth.trim() || null;
}

export function pickTeacherId(req) {
  const header = req.headers.get("x-teacher-id");
  const raw = header;
  const id = Number(raw);
  return Number.isInteger(id) && id > 0 ? id : null;
}

export async function requireCmsAuth(req, env) {
  const token = pickToken(req);
  if (!token) return { error: { status: 401, message: "Missing auth token." } };

  const teacherId = pickTeacherId(req);
  if (!teacherId) return { error: { status: 400, message: "Missing teacher id." } };

  const { ok } = await langoRequest(env, "GET", "/whiteboard/classList", { token });
  if (!ok) return { error: { status: 401, message: "Invalid or expired token." } };

  return { token, teacherId };
}

export async function langoRequest(env, method, endpoint, { token, body } = {}) {
  const base = String(env.LANGO_API_BASE || "https://dev.api.lango.ai/v1");
  const headers = {
    Accept: "application/json",
    "Content-Type": "application/json",
  };
  if (token) headers.Authorization = `Bearer ${token}`;

  const res = await fetch(`${base}${endpoint}`, {
    method,
    headers,
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });

  const text = await res.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch {
    data = { message: text };
  }

  return { ok: res.ok, status: res.status, data };
}
