import { createApiApp } from "./routes/api.js";
import { serveUpload } from "./services/r2-uploads.js";
import { SessionRoom } from "./durable-objects/session-room.js";

export { SessionRoom };

const api = createApiApp();

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // R2 uploads
    if (url.pathname.startsWith("/uploads/")) {
      const uploadResponse = await serveUpload(env, url.pathname);
      if (uploadResponse) return uploadResponse;
      return new Response("Not found", { status: 404 });
    }

    // WebSocket → Durable Object
    if (url.pathname === "/socket.io/" || url.pathname.startsWith("/ws")) {
      const roomId = url.searchParams.get("room");
      if (!roomId) return new Response("Missing room parameter", { status: 400 });
      const id = env.SESSION_ROOM.idFromName(roomId);
      const stub = env.SESSION_ROOM.get(id);
      return stub.fetch(new Request(`https://do/ws?room=${roomId}`, {
        headers: request.headers,
      }));
    }

    // API routes
    if (url.pathname.startsWith("/api/")) {
      return api.fetch(request, env, ctx);
    }

    // Redirect root to host
    if (url.pathname === "/") {
      return Response.redirect(new URL("/host.html", url.origin), 302);
    }

    // Static assets via Workers Assets binding
    return env.ASSETS.fetch(request);
  },
};
