const ALLOWED_IMAGE_TYPES = new Set(["image/jpeg", "image/png", "image/webp", "image/gif"]);
const ALLOWED_IMAGE_EXTS = new Set([".jpg", ".jpeg", ".png", ".webp", ".gif"]);

function extFromMime(mime) {
  const map = {
    "image/jpeg": ".jpg",
    "image/png": ".png",
    "image/webp": ".webp",
    "image/gif": ".gif",
  };
  return map[mime] || ".jpg";
}

function uploadKeyFromUrl(url) {
  const path = String(url || "");
  if (!path.startsWith("/uploads/")) return null;
  return path.slice("/uploads/".length);
}

export async function uploadImage(env, { prefix, ownerId, file }) {
  const mime = file.type || "";
  if (!ALLOWED_IMAGE_TYPES.has(mime)) {
    throw new Error("Only JPEG, PNG, WebP, or GIF images are allowed.");
  }
  if (file.size > 2 * 1024 * 1024) {
    throw new Error("Image must be 2 MB or smaller.");
  }

  const ext = extFromMime(mime);
  const key = `${prefix}/${ownerId}-${Date.now()}${ext}`;
  await env.UPLOADS.put(key, file.stream(), {
    httpMetadata: { contentType: mime },
  });

  return `/uploads/${key}`;
}

export async function deleteUpload(env, uploadUrl) {
  const key = uploadKeyFromUrl(uploadUrl);
  if (!key) return;
  try {
    await env.UPLOADS.delete(key);
  } catch {
    /* ignore missing */
  }
}

export async function serveUpload(env, pathname) {
  const key = uploadKeyFromUrl(pathname);
  if (!key) return null;

  const object = await env.UPLOADS.get(key);
  if (!object) return null;

  const headers = new Headers();
  object.writeHttpMetadata(headers);
  headers.set("Cache-Control", "public, max-age=31536000");
  return new Response(object.body, { headers });
}

export function parseMultipartFile(formData, fieldName) {
  const file = formData.get(fieldName);
  if (!file || typeof file === "string") return null;
  return file;
}

export { ALLOWED_IMAGE_EXTS, uploadKeyFromUrl };
